vector<double> fftAlgo(vector<double>& a, bool invert) {
    int n = a.size();
    for (int i=1, j=0; i<n; i++) {
        int bitmask = n >> 1;
        for (; (j & bitmask) != 0; bitmask >>= 1) {
            j &= ~bitmask;
        }
        j |= bitmask;
        if (i < j) {
            swap(a[i], a[j]);
        }
    }
    for (int len=2; len<=n; len <<=1) {
        double angle = 2 * M_PI / len * (invert ? -1 : 1);
        double wlenCos = cos(angle);
        double wlenSin = sin(angle);
        for (int i=0; i<n; i+=len) {
            double wCos=1, wSin=0;
            for (int j=0; j<len/2; j++) {
                double u= a[i+j], v= a[i+j+len/2]*wCos + a[i+j+len/2]*wSin;
                a[i+j]= u+v;
                a[i+j+len/2]= u-v;
                double tempW = wCos * wlenCos - wSin * wlenSin;
                wSin= wSin*wlenCos + wCos*wlenSin;
                wCos= tempW;
            }
        }
    }
    if (invert) {
        for (int i=0; i<n; i++) {
            a[i] /= n;
        }
    }
    return a;
}

vector<int> polyMultiply(const vector<int>& a, const vector<int>& b, int mod) {
    int n = 1;
    int size = a.size() + b.size() - 1;
    while (n < size) n <<= 1;
    vector<double> A(n, 0), B(n, 0);
    for (int i=0; i<(int)a.size(); i++) {
        int x = ((a[i] % mod) + mod) % mod;
        A[i] = (x & ((1 << 15) - 1)) + (x >> 15) * 1e-6;
    }
    for (int i=0; i<(int)b.size(); i++) {
        int x = ((b[i] % mod) + mod) % mod;
        B[i] = (x & ((1 << 15) - 1)) + (x >> 15) * 1e-6;
    }
    fftAlgo(A, false);
    fftAlgo(B, false);
    vector<double> FA(n), FB(n);
    for (int i=0; i<n; i++) {
        int j = (n - i) & (n - 1);
        double aReal = (A[i] + A[j]) * 0.5;
        double aImag = (A[i] - A[j]) * 0.5;
        double bReal = (B[i] + B[j]) * 0.5;
        double bImag = (B[i] - B[j]) * 0.5;
        FA[i] = aReal * bReal - aImag * bImag;
        FB[i] = aReal * bImag + aImag * bReal;
    }
    fftAlgo(FA, true);
    fftAlgo(FB, true);
    vector<int> res(size);
    for (int i=0; i<size; i++) {
        long long aa = (long long)round(FA[i]);
        long long bb = (long long)round(FB[i]);
        long long val = (aa + ((bb % mod) << 15)) % mod;
        res[i] = (int)val;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
