    while (power > 0) {
        if (power & 1) {
            resultPoly = polyMultiply(resultPoly, v, mod);
        }
        v = polyMultiply(v, v, mod);
        power >>= 1;
    }
    long long total = 0;
    for (int val : resultPoly) {
        total = (total + (long long)val * val) % mod;
    }
    cout << total << "\n";
    return 0;
